INSERT INTO "public"."services" ("id", "name", "description", "base_price", "price_unit", "sale_price", "homepage_description", "weekly_rate", "daily_rate", "service_type", "homepage_price", "homepage_price_unit", "features", "occupancy_model", "mileage_rate", "delivery_fee", "is_taxable", "delivery_fee_is_taxable", "mileage_is_taxable", "show_on_homepage", "display_order", "homepage_highlight", "customer_pickup", "delivery_variant_service_id") VALUES
	(7, 'Premium Insurance', 'Complete protection coverage for your rental', 25.00, '/rental', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'dropoff_only', 0.85, 0, false, true, true, false, 99, NULL, false, NULL),
	(3, 'Rock, Mulch, Gravel', 'Delivery service for landscaping materials. Get rock, mulch, or gravel delivered right to your site.', 125.00, '/delivery', NULL, 'Transform your landscape without the heavy lifting. Seamlessly choose your materials and secure your spot online. We deliver premium-grade rock, mulch, sand, and gravel directly to your home or job site, saving you multiple trips to the supply yard and hours of backbreaking labor.', NULL, 125, 'window', 125, '/delivery', '["Premium landscaping materials available", "Prompt, scheduled driveway delivery", "Perfect for residential & commercial projects", "Bulk savings on large orders", "Priced per yard + flat delivery fee", "Book completely online with ease"]', 'range', 0, 0, true, true, true, true, 4, 'Save Money and Time', false, NULL),
	(2, 'Dump Loader Trailer Rental Service', 'Top-end dump loader with wireless remote, power tarp cover, and hydraulic jack for ease of use. We offer same-day or multiple-day rentals. Pick up starts for our same-day rental at 8 AM, but it must be returned by 10 PM that day. (Pick up location is in South Saratoga Springs.) The Towing vehicle is required to fit: A Ball Hitch Size of (2-5/16").', 105.00, '/full day', NULL, 'Premium 2025 dump trailer equipped with a wireless remote, power tarp cover, and hydraulic jack for ultimate ease of use. Available for single day or multiple day rental.', NULL, 150, 'hourly', 150, '/Per day rental', '["Up to 5 tons capacity", "Easy Self-Serve Rental No-Contact, Hassle-Free", "You pick up and you return or we have delivery available", "Great for junk removal", "Wireless remote control", "Book today, rent as early as tomorrow"]', 'range', 0, 0, true, true, true, true, 1, 'Incredible Value', true, 4),
	(4, 'Dump Loader Trailer with Delivery', 'Delivery service for the dump loader trailer.', 130.00, '/day', NULL, 'Our convenient delivery service for the Dump Loader Trailer. We drop it off and pick it up for you.', NULL, NULL, 'window', NULL, NULL, '[{"name": "Delivery Fee", "value": 40}]', 'range', 0.25, 15, true, true, true, false, 0, NULL, false, NULL),
	(1, '16 Yard Dumpster Rental', '$300 for delivery, pickup, & first day. Plus $50/additional day. Special: Rent for 7 days for only $500!', 100.00, '/delivery & pickup   ', NULL, 'Streamline your next cleanup or renovation project with our residential-friendly 16-yard roll-off dumpsters. Designed to fit easily in standard driveways, they offer the perfect balance of massive capacity and a compact footprint for hassle-free waste disposal.', 500, 50, 'window', NULL, NULL, '["Up to 2.5 tons capacity", "100% contactless delivery & pickup available", "Perfect for home renovations & cleanouts", "Low-profile sides for easy loading", "Optional driveway protective available", "Book today, delivery as early as tomorrow"]', 'range', 0.55, 30, true, true, true, true, 2, 'Our Most Popular Service', false, NULL),
	(5, 'DIY Heavy Equipment', 'Tackle tough backyard projects without the strain. Our compact machinery fits through standard yard gates to deliver heavy-duty digging and lifting power in tight spaces.', 105.00, '/full day', NULL, 'Tackle tough backyard projects without the strain. Our compact machinery fits through standard yard gates to deliver heavy-duty digging and lifting power in tight spaces.', NULL, 150, 'hourly', 150, '/Per day rental', '["You pick up & return or we have delivery available", "Easy Self-Serve Rental No-Contact, Hassle-Free", "Great for digging and trenching", "Fits through gates & narrow spaces", "Book today, rent as early as tomorrow", "Saves days of hard physical labor"]', 'range', 0, 0, true, true, true, true, 3, 'Save Your Back & Time', true, NULL);
